const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${svgPaths[name]||svgPaths['arrow-right']}</svg>`;
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(e=>{const n=e.dataset.icon;e.outerHTML=icon(n)});}
function wa(message){return `https://wa.me/5511932362552?text=${encodeURIComponent(message)}`}
function hydrateLinks(){document.querySelectorAll('[data-wa]').forEach(a=>a.href=wa(a.dataset.wa))}
const $=s=>document.querySelector(s);
let properties=[],visibleCount=6,filters={region:'all',beds:'all',status:'all',saved:false,q:''},compare=new Set(),heroIndex=0;
let favorites=new Set();try{const v=JSON.parse(localStorage.getItem('ferrari-favorites')||'[]');if(Array.isArray(v))favorites=new Set(v.filter(x=>typeof x==='string'))}catch{}
const featureIds=['sinfonia','vision','mob-barra'];
const featuredOrder=['sinfonia','atlas','vision','line-praca','mob-barra','origem','mob-campo','iconico','line-parada','serena','altus','villagio'];
const regions={all:'Todas as regiões',sul:'Zona Sul',leste:'Zona Leste',oeste:'Zona Oeste',norte:'Zona Norte',jundiai:'Jundiaí'};
const bedsLabel=p=>p.beds.length===2?'1 e 2 dormitórios':`${p.beds[0]} dormitório${p.beds[0]>1?'s':''}`;
let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function persistFavorites(){try{localStorage.setItem('ferrari-favorites',JSON.stringify([...favorites]))}catch{}updateSavedCounter()}
function updateSavedCounter(){const count=$('#saved-count');count.textContent=favorites.size;count.hidden=favorites.size===0;$('#saved-btn').setAttribute('aria-label',`Ver ${favorites.size} ${favorites.size===1?'imóvel':'imóveis'} favorito${favorites.size!==1?'s':''}`)}
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function filteredProperties(){let result=properties.filter(p=>(filters.region==='all'||p.region===filters.region)&&(filters.beds==='all'||p.beds.includes(+filters.beds))&&(filters.status==='all'||p.status===filters.status)&&(!filters.saved||favorites.has(p.id))&&(!(filters.q||'').trim()||normalize(p.name+' '+p.neighborhood+' '+p.regionLabel+' '+p.city).includes(normalize(filters.q.trim()))));switch($('#sort-select').value){case'name':result.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));break;case'area':result.sort((a,b)=>parseFloat(b.area.split(' a ').at(-1))-parseFloat(a.area.split(' a ').at(-1)));break;case'ready':result.sort((a,b)=>(a.status==='Pronto para morar'?-1:0)-(b.status==='Pronto para morar'?-1:0));break;default:result.sort((a,b)=>featuredOrder.indexOf(a.id)-featuredOrder.indexOf(b.id));}return result}
function renderCards(){const result=filteredProperties();const shown=result.slice(0,visibleCount);$('#property-grid').innerHTML=shown.map(p=>`<article class="property-card"><div class="card-image-wrap"><a class="image-open" href="/imoveis/${p.id}/" data-open="${p.id}" aria-label="Conhecer ${p.name}"><img class="card-image" src="${p.image}" alt="Perspectiva ilustrativa de ${p.name}" loading="lazy" width="700" height="440" ${window.FerrariUI.imageAttributes(p)}></a><span class="status-badge ${p.status==='Lançamento'?'launch':p.status==='Pronto para morar'?'ready':''}">${p.status}</span><button class="favorite" data-save="${p.id}" aria-label="${favorites.has(p.id)?'Remover':'Salvar'} ${p.name} ${favorites.has(p.id)?'dos':'nos'} favoritos" aria-pressed="${favorites.has(p.id)}">${icon('heart')}</button></div><div class="card-body"><p class="card-location">${icon('pin')} ${p.neighborhood} · ${p.region==='jundiai'?'Jundiaí':p.regionLabel}</p><a class="card-title" href="/imoveis/${p.id}/" data-open="${p.id}"><h3>${p.name}</h3></a><p class="card-highlight">${p.highlight}</p><div class="card-specs"><span>${icon('bed')}${bedsLabel(p)}</span><span>${icon('area')}${p.area} m²</span></div><div class="card-footer"><label class="compare-option"><input type="checkbox" aria-label="Comparar ${p.name}" data-compare="${p.id}" ${compare.has(p.id)?'checked':''}> Comparar</label><a class="card-more" href="/imoveis/${p.id}/" data-open="${p.id}">Conheça o imóvel ${icon('arrow-up-right')}</a></div></div></article>`).join('');$('#empty-state').hidden=result.length>0;$('#result-count').textContent=`${result.length} empreendimento${result.length!==1?'s':''}${filters.saved?' favorito'+(result.length!==1?'s':''):''}${result.length>shown.length?` · ${shown.length} em exibição`:''}`;$('#load-more').hidden=result.length<=visibleCount;document.querySelectorAll('[data-region]').forEach(b=>{const active=b.dataset.region===filters.region;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});$('#favorites-filter').setAttribute('aria-pressed',filters.saved);$('#region-select').value=filters.region;$('#beds-select').value=filters.beds;$('#status-select').value=filters.status; updateFilterUX();}
function scrollToCatalog(){document.getElementById('imoveis').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
function resetFilters(){filters={region:'all',beds:'all',status:'all',saved:false,q:''};visibleCount=6;$('#sort-select').value='featured';renderCards()}
function showDialog(dialog){if(!dialog.open)dialog.showModal()}
function openDetail(id){const p=properties.find(x=>x.id===id);if(!p)return;const l=p.links;$('#detail-content').innerHTML=`<div class="detail-top"><div class="detail-photo"><img id="detail-photo" src="${p.image}" alt="Perspectiva ilustrativa de ${p.name}" width="700" height="440" ${window.FerrariUI.imageAttributes(p,'(max-width: 900px) 100vw, 50vw')}><small>Imagem ilustrativa</small><button class="photo-toggle" data-photo="${p.id}" aria-pressed="false">${icon('image')} Ver fachada</button></div><div class="detail-info"><p class="eyebrow"><span></span>${p.neighborhood.toUpperCase()} · ${p.city.toUpperCase()}</p><h2 id="detail-title">${p.name}</h2><span class="detail-status">${p.status}</span><p>${p.description}</p><div class="detail-specs"><div><small>Plantas</small>${bedsLabel(p)}</div><div><small>Metragem do portfólio</small>${p.area} m²</div><div><small>Diferencial</small>${p.highlight}</div><div><small>${p.delivery?'Previsão de entrega':'Fase'}</small>${p.delivery||'Pronto para morar'}</div></div><p class="detail-address">${icon('pin')}${p.address}</p><a class="btn btn-red" href="${wa(`Olá! Tenho interesse no ${p.name}, em ${p.neighborhood}. Gostaria de consultar valores, disponibilidade e condições.`)}" target="_blank" rel="noopener noreferrer">${icon('whatsapp')} Consultar condições ${icon('arrow-up-right')}</a><a class="text-link" href="${wa(`Olá! Gostaria de agendar uma visita ao ${p.name}. Quais são as possibilidades?`)}" target="_blank" rel="noopener noreferrer">Quero agendar uma visita ${icon('arrow-right')}</a><div class="detail-utilities"><a href="/imoveis/${p.id}/">Página completa ${icon('arrow-up-right')}</a><button data-share="${p.id}">${icon('share')} Compartilhar</button></div></div></div><div class="detail-bottom"><div><h3>Mais possibilidades no dia a dia.</h3><div class="amenities">${p.amenities.map(a=>`<span>${icon('check')}${a}</span>`).join('')}</div></div><div><h3>Explore os detalhes.</h3><div class="resource-links">${l.tour?`<a href="${l.tour}" target="_blank" rel="noopener noreferrer">${icon('play')}Tour virtual</a>`:''}${l.book?`<a href="${l.book}" target="_blank" rel="noopener noreferrer">${icon('file')}Apresentação</a>`:''}${l.imagens?`<a href="${l.imagens}" target="_blank" rel="noopener noreferrer">${icon('image')}Mais imagens</a>`:''}${l.map?`<a href="${l.map}" target="_blank" rel="noopener noreferrer">${icon('pin')}Ver localização</a>`:''}</div><p>Imagens ilustrativas. Confirme metragens, itens incluídos, disponibilidade, endereço e previsões com o atendimento.<br><small>Referências: portfólio set/2026 e material institucional EMCCAMP fornecido.</small></p></div></div>`;$('#detail-dialog').setAttribute('aria-labelledby','detail-title');showDialog($('#detail-dialog'));history.replaceState(null,'',`#imovel/${p.id}`)}
function renderHero(){const p=properties.find(x=>x.id===featureIds[heroIndex]);if(!p)return;const heroImage=$('#hero-image');heroImage.srcset=(p.responsive||[]).map(image=>`/${image.src} ${image.width}w`).join(', ');heroImage.sizes='(max-width: 900px) 100vw, 67vw';heroImage.src=p.image;if(!matchMedia('(prefers-reduced-motion: reduce)').matches)$('#hero-image').animate([{opacity:.45},{opacity:1}],{duration:450,easing:'ease-out'});$('#hero-image').alt=`Perspectiva ilustrativa de ${p.name}`;$('#hero-location').textContent=`${p.regionLabel.toUpperCase()} · ${p.city.toUpperCase()}`;$('#hero-name').textContent=p.name;$('.hero-property').dataset.open=p.id;$('#hero-spec').textContent=`${bedsLabel(p)} · ${p.area} m² · ${p.id==='vision'?'com suíte e vaga':p.id==='sinfonia'?'com varanda':'plantas compactas'}`;$('#hero-number').innerHTML=`0${heroIndex+1} <small>/ 03</small>`;$('.hero-progress').innerHTML=featureIds.map((_,i)=>`<b style="background:${i===heroIndex?'#fff':'#ffffff50'}"></b>`).join('')}
function updateCompare(){const selected=properties.filter(p=>compare.has(p.id));$('#compare-bar').hidden=selected.length===0;$('#compare-label').textContent=`${selected.length} ${selected.length===1?'imóvel':'imóveis'} selecionado${selected.length>1?'s':''}`;$('#compare-names').textContent=selected.map(p=>p.name).join(' · ');$('#open-compare').disabled=selected.length<2;$('#open-compare').title=selected.length<2?'Selecione pelo menos 2 imóveis':'Comparar imóveis selecionados';}
function openCompare(){const selected=properties.filter(p=>compare.has(p.id));if(selected.length<2)return;$('#compare-content').innerHTML=`<div class="compare-grid" style="grid-template-columns:repeat(${selected.length},minmax(0,1fr))">${selected.map(p=>`<article class="compare-item"><img src="${p.image}" alt="${p.name}" width="700" height="440"><h3>${p.name}</h3><p>${p.neighborhood} · ${p.regionLabel}</p><dl><div><dt>Planta</dt><dd>${bedsLabel(p)}</dd></div><div><dt>Área</dt><dd>${p.area} m²</dd></div><div><dt>Fase</dt><dd>${p.status}</dd></div><div><dt>Entrega prevista</dt><dd>${p.delivery||'Consultar unidade'}</dd></div><div><dt>Destaque</dt><dd>${p.highlight}</dd></div></dl><a class="btn btn-red" href="${wa(`Olá! Estou comparando ${selected.map(x=>x.name).join(', ')} e gostaria de saber mais sobre o ${p.name}.`)}" target="_blank" rel="noopener noreferrer">Consultar condições ${icon('arrow-up-right')}</a></article>`).join('')}</div>`;showDialog($('#compare-dialog'))}
let quizStep=0,quizAnswers={region:null,beds:null,status:null};
const quizQuestions=[{key:'region',title:'Onde você imagina<br>sua próxima história?',text:'Escolha a região que faz sentido para a sua rotina.',options:[['sul','Zona Sul'],['leste','Zona Leste'],['oeste','Zona Oeste'],['norte','Zona Norte'],['jundiai','Jundiaí'],['all','Quero explorar todas']]},{key:'beds',title:'Quanto espaço<br>combina com você?',text:'Um começo mais compacto ou espaço para novos planos?',options:[['1','1 dormitório'],['2','2 dormitórios'],['all','Quero ver as possibilidades']]},{key:'status',title:'Qual é o seu<br>momento de vida?',text:'Encontre opções para o seu tempo.',options:[['Lançamento','Quero conhecer lançamentos'],['Em obras','Posso planejar a mudança'],['Pronto para morar','Procuro algo pronto'],['all','Estou explorando opções']]}];
function quizMatches(){return properties.filter(p=>(quizAnswers.region==='all'||p.region===quizAnswers.region)&&(quizAnswers.beds==='all'||p.beds.includes(+quizAnswers.beds))&&(quizAnswers.status==='all'||p.status===quizAnswers.status))}
function renderQuiz(){if(quizStep===3){const matches=quizMatches();const message=`Olá, Ferrari! Busco um imóvel em ${regions[quizAnswers.region]}, com ${quizAnswers.beds==='all'?'1 ou 2 dormitórios':quizAnswers.beds+' dormitório(s)'}. Meu momento: ${quizAnswers.status==='all'?'estou explorando opções':quizAnswers.status}.${matches.length?' Me interessei por '+matches.slice(0,3).map(p=>p.name).join(', ')+'.':''} Podem me ajudar?`;$('#quiz-content').innerHTML=`<p class="eyebrow"><span></span>SEU PONTO DE PARTIDA</p><h2>${matches.length?'Sua próxima história<br>já tem possibilidades.':'Vamos encontrar<br>outros caminhos.'}</h2><p>${matches.length?'Encontramos imóveis que combinam com suas escolhas.':'Essa combinação não tem opções no catálogo no momento. O atendimento pode ajudar a explorar alternativas.'}</p><div class="quiz-result"><strong>${matches.length} ${matches.length===1?'possibilidade encontrada':'possibilidades encontradas'}</strong><p>${regions[quizAnswers.region]} · ${quizAnswers.beds==='all'?'1 ou 2':quizAnswers.beds} dormitório${quizAnswers.beds==='1'?'':'s'} · ${quizAnswers.status==='all'?'Todas as fases':quizAnswers.status}</p><div class="quiz-result-list">${matches.slice(0,3).map(p=>`<span>↗ ${p.name}</span>`).join('')}</div></div><div class="quiz-final-actions">${matches.length?`<button class="btn btn-dark" id="quiz-view">Explorar meus imóveis ${icon('arrow-right')}</button>`:''}<a class="btn btn-red" href="${wa(message)}" target="_blank" rel="noopener noreferrer">${icon('whatsapp')}Conversar com a Ferrari</a></div><button class="text-btn" id="quiz-restart">Refazer minhas escolhas</button>`;return}const q=quizQuestions[quizStep];$('#quiz-content').innerHTML=`<div class="quiz-progress">${[0,1,2].map(i=>`<b class="${i<=quizStep?'done':''}"></b>`).join('')}</div><p class="eyebrow">PASSO 0${quizStep+1} DE 03</p><h2>${q.title}</h2><p>${q.text}</p><div class="quiz-options">${q.options.map(([value,label])=>`<button data-quiz-value="${value}" class="${quizAnswers[q.key]===value?'selected':''}" aria-pressed="${quizAnswers[q.key]===value}">${label}</button>`).join('')}</div><div class="quiz-actions"><button class="text-btn" id="quiz-back">${quizStep?icon('arrow-left')+' Voltar':'Cancelar'}</button><button class="btn btn-red" id="quiz-next" ${quizAnswers[q.key]===null?'disabled':''}>${quizStep===2?'Ver minhas opções':'Continuar'} ${icon('arrow-right')}</button></div>`}
function initEvents(){
// Shared navigation behavior is initialized by FerrariUI.
$('#main-nav').addEventListener('click',e=>{if(e.target.closest('a')){$('#main-nav').classList.remove('open');$('#menu-btn').setAttribute('aria-expanded','false');$('#menu-btn').setAttribute('aria-label','Abrir menu')}});
$('#search-form').addEventListener('submit',e=>{e.preventDefault();filters={q:$('#catalog-search').value,region:$('#region-select').value,beds:$('#beds-select').value,status:$('#status-select').value,saved:false};visibleCount=6;renderCards();scrollToCatalog()});
$('#sort-select').addEventListener('change',renderCards);$('#clear-filters').addEventListener('click',resetFilters);$('#load-more').addEventListener('click',()=>{const previous=visibleCount;visibleCount=12;renderCards();document.querySelectorAll('.card-title')[previous]?.focus({preventScroll:true})});
$('#favorites-filter').addEventListener('click',()=>{filters.saved=!filters.saved;visibleCount=12;renderCards()});$('#saved-btn').addEventListener('click',()=>{filters={region:'all',beds:'all',status:'all',saved:true,q:''};visibleCount=12;renderCards();scrollToCatalog()});
$('#hero-next').addEventListener('click',()=>{heroIndex=(heroIndex+1)%featureIds.length;renderHero()});$('#hero-prev').addEventListener('click',()=>{heroIndex=(heroIndex+featureIds.length-1)%featureIds.length;renderHero()});
$('#open-compare').addEventListener('click',openCompare);$('#clear-compare').addEventListener('click',()=>{compare.clear();updateCompare();renderCards()});
$('#open-quiz').addEventListener('click',()=>{quizStep=0;quizAnswers={region:null,beds:null,status:null};renderQuiz();showDialog($('#quiz-dialog'))});
$('#privacy-btn').addEventListener('click',()=>showDialog($('#privacy-dialog')));$('#erase-favorites').addEventListener('click',()=>{favorites.clear();persistFavorites();renderCards();toast('Seus favoritos foram apagados deste navegador.')});
document.addEventListener('click',e=>{
 const open=e.target.closest('[data-open]');if(open){if(open.tagName==='A'&&(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||e.button!==0))return;e.preventDefault();openDetail(open.dataset.open);return}
 const save=e.target.closest('[data-save]');if(save){const id=save.dataset.save;if(favorites.has(id)){favorites.delete(id);toast('Imóvel removido dos favoritos.')}else{favorites.add(id);toast('Imóvel salvo nos seus favoritos.')}persistFavorites();renderCards();document.querySelector(`[data-save="${id}"]`)?.focus({preventScroll:true});return}
 const region=e.target.closest('[data-region]');if(region){filters.region=region.dataset.region;visibleCount=6;renderCards();return}
 const life=e.target.closest('[data-lifestyle]');if(life){resetFilters();if(life.dataset.lifestyle==='first')filters.beds='1';if(life.dataset.lifestyle==='family')filters.beds='2';if(life.dataset.lifestyle==='ready')filters.status='Pronto para morar';renderCards();scrollToCatalog();return}
 const photo=e.target.closest('[data-photo]');if(photo){const p=properties.find(x=>x.id===photo.dataset.photo);const active=photo.getAttribute('aria-pressed')==='true';const photoImage=$('#detail-photo');photoImage.srcset=active?(p.responsive||[]).map(image=>`/${image.src} ${image.width}w`).join(', '):'';photoImage.src=active?p.image:p.facade;photo.setAttribute('aria-pressed',!active);photo.innerHTML=icon('image')+(active?' Ver fachada':' Ver perspectiva');return}
 const close=e.target.closest('.dialog-close');if(close){close.closest('dialog').close();return}
 const quizChoice=e.target.closest('[data-quiz-value]');if(quizChoice){quizAnswers[quizQuestions[quizStep].key]=quizChoice.dataset.quizValue;renderQuiz();return}
 if(e.target.closest('#quiz-next')){if(quizAnswers[quizQuestions[quizStep].key]!==null){quizStep++;renderQuiz()}return}
 if(e.target.closest('#quiz-back')){if(quizStep>0){quizStep--;renderQuiz()}else $('#quiz-dialog').close();return}
 if(e.target.closest('#quiz-restart')){quizStep=0;quizAnswers={region:null,beds:null,status:null};renderQuiz();return}
 if(e.target.closest('#quiz-view')){filters={...quizAnswers,saved:false};visibleCount=12;renderCards();$('#quiz-dialog').close();scrollToCatalog();return}
});
document.addEventListener('change',e=>{if(e.target.matches('[data-compare]')){const id=e.target.dataset.compare;if(e.target.checked){if(compare.size>=3){e.target.checked=false;toast('Compare até 3 imóveis por vez.');return}compare.add(id)}else compare.delete(id);updateCompare()}});
document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});$('#detail-dialog').addEventListener('close',()=>{if(location.hash.startsWith('#imovel/'))history.replaceState(null,'','#imoveis')});window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#imovel/'))openDetail(location.hash.split('/')[1])});
}
hydrateIcons();hydrateLinks();updateSavedCounter();initEvents();
const phaseKeys={'Lançamento':'lancamento','Em obras':'obras','Pronto para morar':'pronto'};
const phaseValues={lancamento:'Lançamento',obras:'Em obras',pronto:'Pronto para morar'};
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function restoreFilterURL(){const u=new URL(location.href);const r=u.searchParams.get('regiao'),b=u.searchParams.get('dormitorios'),phase=u.searchParams.get('fase'),sort=u.searchParams.get('ordem');filters={region:Object.hasOwn(regions,r)?r:'all',beds:['1','2'].includes(b)?b:'all',status:phaseValues[phase]||'all',saved:false,q:(u.searchParams.get('busca')||'').slice(0,120)};if(['featured','name','area','ready'].includes(sort))$('#sort-select').value=sort;$('#catalog-search').value=filters.q;}
function updateFilterUX(){
 const q=filters.q||'';if(document.activeElement!==$('#catalog-search'))$('#catalog-search').value=q;
 const chips=[];if(filters.region!=='all')chips.push(['region',regions[filters.region]]);if(filters.beds!=='all')chips.push(['beds',filters.beds+' dormitório'+(filters.beds==='2'?'s':'')]);if(filters.status!=='all')chips.push(['status',filters.status]);if(q.trim())chips.push(['q','Busca: '+q.trim()]);if(filters.saved)chips.push(['saved','Favoritos']);
 $('#active-filters').innerHTML=chips.map(([key,label])=>`<button data-remove-filter="${key}" aria-label="Remover filtro ${escapeHTML(label)}">${escapeHTML(label)} ${icon('x')}</button>`).join('')+(chips.length>1?'<button class="clear-all-filters" data-reset-filters>Limpar tudo</button>':'');
 const url=new URL(location.href);for(const key of ['regiao','dormitorios','fase','busca','ordem'])url.searchParams.delete(key);if(filters.region!=='all')url.searchParams.set('regiao',filters.region);if(filters.beds!=='all')url.searchParams.set('dormitorios',filters.beds);if(filters.status!=='all')url.searchParams.set('fase',phaseKeys[filters.status]);if(q.trim())url.searchParams.set('busca',q.trim());if($('#sort-select').value!=='featured')url.searchParams.set('ordem',$('#sort-select').value);if(url.href!==location.href)history.replaceState(null,'',url);
 if(!filteredProperties().length){$('#empty-state h3').textContent=filters.saved?'Sua seleção começa aqui.':'Vamos ampliar as possibilidades?';$('#empty-state p').textContent=filters.saved?'Toque no coração de um imóvel para guardar suas opções favoritas.':'Não encontramos imóveis com essa combinação. Experimente ajustar os filtros.';}
}
function initRefinements(){
 window.FerrariUI?.init();let queryTimer;
 $('#catalog-search').addEventListener('input',()=>{clearTimeout(queryTimer);queryTimer=setTimeout(()=>{filters.q=$('#catalog-search').value;visibleCount=6;renderCards()},180)});
 $('#catalog-search').addEventListener('keydown',e=>{if(e.key==='Enter'){clearTimeout(queryTimer);filters.q=$('#catalog-search').value;visibleCount=12;renderCards()}});
 document.addEventListener('click',e=>{
  const navRegion=e.target.closest('[data-nav-region]'),navStatus=e.target.closest('[data-nav-status]');
  if(navRegion||navStatus){if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();resetFilters();if(navRegion)filters.region=navRegion.dataset.navRegion;if(navStatus)filters.status=navStatus.dataset.navStatus;visibleCount=12;renderCards();$('#property-menu').open=false;$('#main-nav').classList.remove('open');$('#menu-btn').setAttribute('aria-expanded','false');scrollToCatalog();}
  const chip=e.target.closest('[data-remove-filter]');if(chip){const key=chip.dataset.removeFilter;filters[key]=key==='saved'?false:key==='q'?'':'all';visibleCount=6;renderCards();$('#catalog-search').focus({preventScroll:true})}
  if(e.target.closest('[data-reset-filters]')){resetFilters();$('#catalog-search').focus({preventScroll:true})}
  const share=e.target.closest('[data-share]');if(share){const p=properties.find(p=>p.id===share.dataset.share);if(p)window.FerrariUI.share(p.name,new URL(`/imoveis/${p.id}/`,document.querySelector('link[rel=canonical]').href).href,share,toast);}
 });
 window.addEventListener('popstate',()=>{restoreFilterURL();renderCards()});
}

function startCatalog(data){properties=data;restoreFilterURL();renderCards();updateCompare();initRefinements();if(location.hash.startsWith('#imovel/'))openDetail(location.hash.split('/')[1]);}
try{const embedded=document.getElementById('property-data');if(embedded)startCatalog(JSON.parse(embedded.textContent));else fetch('/properties.json').then(r=>{if(!r.ok)throw Error('Catálogo indisponível');return r.json()}).then(startCatalog).catch(()=>toast('O catálogo está disponível abaixo. Consulte condições pelo WhatsApp.'));}catch(error){console.error('Não foi possível iniciar os filtros.',error);toast('Explore os imóveis abaixo ou fale com a Ferrari.');}
